车辆层次结构
```sysml
package VehicleHierarchy {
    // 基础定义
    abstract part def Vehicle {
        attribute mass: Real;
        attribute maxSpeed: Real;
        abstract part powertrain: Powertrain;
    }

abstract part def Powertrain {
        attribute power: Real;
    }

// 特化层次
    part def GroundVehicle :> Vehicle {
        attribute wheelCount: Integer;
    }

part def Car :> GroundVehicle {
        attribute wheelCount :>> GroundVehicle::wheelCount = 4;
        part powertrain :>> Vehicle::powertrain: CarPowertrain;
    }

part def CarPowertrain :> Powertrain {
        part engine: Engine;
        part transmission: Transmission;
    }

// 进一步特化
    part def ElectricCar :> Car {
        part powertrain :>> Car::powertrain: ElectricPowertrain;
    }

part def ElectricPowertrain :> CarPowertrain {
        part engine :>> CarPowertrain::engine: ElectricMotor;
        part battery: Battery;
    }

---

